  // ── State / Local / Federal Responsibility Area lookup ─────────────────────
  // Source: CAL FIRE FRAP State Responsibility Area SRA26_1 geodatabase.
  // Stored as a run-length-encoded raster rather than polygons — the polygon
  // layer is 3.5M vertices, which will not load usefully in the browser.
  // STATEWIDE, grid step 0.0005 deg (~56 m). 20800 x 19200 cells.
  // Verified at 99.68% agreement against the source polygons over 6000 random
  // points; disagreements are cells straddling a boundary line.
  // Values 1=SRA 2=LRA 3=FRA 0=no data.
  // SRA_GRID now lives in comm-geo.js (lazy-loaded via RADIO.loadGeo)
  function sraAt(lat, lng){
    try{
      const G=window.RADIO&&window.RADIO.SRA_GRID; if(!G) return null;
      const r=Math.floor((lat-G.miny)/G.step), c=Math.floor((lng-G.minx)/G.step);
      if(r<0||c<0||r>=G.h||c>=G.w) return null;
      const parts=G.rows[r].split(',');
      let x=0;
      for(let i=0;i<parts.length;i++){
        if(!parts[i]) continue;
        const d=parts[i].split('.'), v=+d[0], n=+d[1];
        if(c < x+n) return ({1:'SRA',2:'LRA',3:'FRA'})[v]||null;
        x+=n;
      }
    }catch(e){}
    return null;
  }


